{"styles":{"css":"/* === DXS Archive Hub — Hero === */
.wpcom-ai-archive-hero-title.wp-block-query-title {
	position: relative;
	z-index: 1;
}

/* === Card grid === */
.wpcom-ai-card-body {
	transition: box-shadow .2s ease;
}

.wpcom-ai-card-body:hover {
	box-shadow: 0 8px 32px rgba(0,0,0,0.10);
}

.wpcom-ai-card-image.wp-block-post-featured-image img {
	transition: transform .35s ease;
	display: block;
	width: 100%;
}

.wpcom-ai-card-image.wpcom-ai-card-image:hover img {
	transform: scale(1.03);
}

.wpcom-ai-card-title a {
	color: inherit !important;
	text-decoration: none !important;
}

.wpcom-ai-card-title a:hover {
	text-decoration: underline !important;
}

/* === Lead story === */
.wpcom-ai-lead-title a {
	color: inherit !important;
	text-decoration: none !important;
}

.wpcom-ai-lead-title a:hover {
	text-decoration: underline !important;
}

.wpcom-ai-lead-category a {
	text-decoration: none !important;
	color: inherit !important;
}

.wpcom-ai-lead-rule.wp-block-separator {
	border-top: 2px solid #1E1E1E;
	margin: 0;
}

/* === Pagination === */
.wpcom-ai-pagination .wp-block-query-pagination-numbers a,
.wpcom-ai-pagination .wp-block-query-pagination-previous a,
.wpcom-ai-pagination .wp-block-query-pagination-next a {
	text-decoration: none;
	font-weight: 600;
	color: #1E1E1E;
	border-bottom: 2px solid transparent;
	transition: border-color .15s ease;
}

.wpcom-ai-pagination .wp-block-query-pagination-numbers a:hover,
.wpcom-ai-pagination .wp-block-query-pagination-previous a:hover,
.wpcom-ai-pagination .wp-block-query-pagination-next a:hover {
	border-bottom-color: #1E1E1E;
}

.wpcom-ai-pagination .wp-block-query-pagination-numbers .current {
	font-weight: 800;
	border-bottom: 2px solid #1E1E1E;
}

/* === Newsletter button === */
.wpcom-ai-newsletter-btn .wp-block-button__link {
	letter-spacing: .25px;
	transition: opacity .15s ease;
}

.wpcom-ai-newsletter-btn .wp-block-button__link:hover {
	opacity: .88;
}

/* === Responsive stacking === */
@media (max-width: 768px) {
	.wpcom-ai-hero-section {
		padding-left: 1.5rem !important;
		padding-right: 1.5rem !important;
	}

	.wpcom-ai-grid-section {
		padding-left: 1rem !important;
		padding-right: 1rem !important;
	}
